WITH yearly_medians AS (
  SELECT annee, PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY prix_m2) AS median
  FROM dvf.ventes
  WHERE code_commune = '33063' AND type_bien = 'Appartement' AND vente_reference = true
  GROUP BY annee
)
SELECT ROUND(
  (POWER(
    (SELECT median FROM yearly_medians WHERE annee = 2025),
    1.0 / (2025 - 2021)
  ) / (SELECT median FROM yearly_medians WHERE annee = 2021) - 1) * 100, 
  1
) AS cagr FROM yearly_medians LIMIT 1;

